const money = n => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(n)||0);


function ProductReviews({productId}) {
 const [data,setData]=useState({items:[],review_count:0,average_rating:0});
 const [loading,setLoading]=useState(true),[error,setError]=useState(''),[name,setName]=useState(''),[rating,setRating]=useState(5),[review,setReview]=useState(''),[sending,setSending]=useState(false),[message,setMessage]=useState('');
 useEffect(()=>{let active=true;async function load(){setLoading(true);setError('');try{const response=await fetch(API_PATH('/products/'+productId+'/reviews'));if(!response.ok)throw Error('Unable to load reviews');const json=await response.json();if(active)setData({items:Array.isArray(json.items)?json.items:[],review_count:Number(json.review_count||0),average_rating:Number(json.average_rating||0)});}catch{if(active)setError('Reviews are temporarily unavailable.');}finally{if(active)setLoading(false)}}if(productId)load();return()=>{active=false}},[productId]);
 async function submit(event){event.preventDefault();setMessage('');setError('');if(!name.trim()||review.trim().length<3){setError('Enter your name and a review of at least 3 characters.');return}setSending(true);try{const response=await fetch(API_PATH('/products/'+productId+'/reviews'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reviewer_name:name.trim(),rating:Number(rating),review_text:review.trim()})});const json=await response.json().catch(()=>({}));if(!response.ok)throw Error(json.detail||'Could not submit your review.');setMessage(json.message||'Thank you. Your review has been published.');setName('');setReview('');setRating(5);}catch(e){setError(e.message||'Review submission failed. Please try again.')}finally{setSending(false)}}
 return <section className="product-reviews" aria-labelledby="reviews-heading"><div className="reviews-heading"><div><span className="overline">REAL SHOPPER FEEDBACK</span><h2 id="reviews-heading">Ratings &amp; reviews</h2></div><div className="reviews-summary"><strong>{data.average_rating.toFixed(1)} ★</strong><span>{data.review_count} {data.review_count===1?'review':'reviews'}</span></div></div>
 {loading?<p className="reviews-note">Loading reviews…</p>:error&&data.items.length===0?<p className="reviews-note">{error}</p>:data.items.length===0?<p className="reviews-note">No reviews yet. Be the first to share your experience.</p>:<div className="review-list">{data.items.map(item=><article className="review-item" key={item.id}><div className="review-item-top"><strong>{item.reviewer_name}</strong><span aria-label={item.rating+' out of 5 stars'}>{'★'.repeat(item.rating)}{'☆'.repeat(5-item.rating)}</span></div><p>{item.review_text}</p><small>{item.created_at?new Date(item.created_at).toLocaleDateString():''}</small></article>)}</div>}
 <form className="review-form" onSubmit={submit}><h3>Write a review</h3><p>Your review appears automatically unless the text contains flagged abusive language.</p><label>Your name<input value={name} onChange={e=>setName(e.target.value)} maxLength={80} required placeholder="Enter your name"/></label><label>Your rating<select value={rating} onChange={e=>setRating(Number(e.target.value))}><option value={5}>5 — Excellent</option><option value={4}>4 — Good</option><option value={3}>3 — Average</option><option value={2}>2 — Poor</option><option value={1}>1 — Very poor</option></select></label><label>Your review<textarea value={review} onChange={e=>setReview(e.target.value)} minLength={3} maxLength={2000} rows={4} required placeholder="What did you think about this product?"/></label>{error&&<p className="review-feedback error" role="alert">{error}</p>}{message&&<p className="review-feedback success" role="status">{message}</p>}<button className="primary-cta" type="submit" disabled={sending}>{sending?'Submitting…':'Submit review'} <span>→</span></button><small className="review-disclaimer">Reviewer names are entered by users and are not identity-verified.</small></form></section>
}

function ProductPriceHistory({variantId}) {
 const [history,setHistory]=useState(null),[open,setOpen]=useState(false);
 useEffect(()=>{let active=true;async function load(){try{const r=await fetch(API_PATH('/products/variants/'+variantId+'/price-history?days=30'));if(!r.ok)throw Error();const j=await r.json();if(active)setHistory(j)}catch{if(active)setHistory({available:false,items:[]})}}if(variantId)load();return()=>{active=false}},[variantId]);
 const points=history?.items||[];
 const prices=points.map(x=>Number(x.selling_price)).filter(Number.isFinite);
 const lowest=prices.length?Math.min(...prices):null;
 const fmt=n=>money(n);
 return <section className="price-history-card"><button className="price-history-toggle" type="button" aria-expanded={open} onClick={()=>setOpen(v=>!v)}><span><strong>30-day price history</strong><small>{lowest!==null?'Lowest recorded price: '+fmt(lowest):'Price history building'}</small></span><span className="price-history-chevron">{open?'−':'＋'}</span></button>{open&&<div className="price-history-content">{points.length>=2?<><div className="price-history-chart" role="img" aria-label="Recorded selling prices over the last 30 days">{points.map((p,i)=>{const min=Math.min(...prices),max=Math.max(...prices),range=max-min||1;return <div className="price-history-point" key={p.recorded_at||i} title={new Date(p.recorded_at).toLocaleDateString()+': '+fmt(p.selling_price)}><span style={{height:(22+((Number(p.selling_price)-min)/range)*78)+'%'}}/></div>})}</div><div className="price-history-legend"><span>{new Date(points[0].recorded_at).toLocaleDateString()}</span><span>Lowest: <b>{fmt(lowest)}</b></span><span>{new Date(points[points.length-1].recorded_at).toLocaleDateString()}</span></div></>:<p className="price-history-empty">Price history is building from real catalogue records. Historical prices will appear here as they are recorded; no estimates are shown.</p>}</div>}</section>
}

