 async function load(silent=false){if(!silent)setLoading(true);setError('');try{let rows=[];let offset=0;while(true){const r=await fetch(API_PATH(`/products?limit=100&offset=${offset}`));if(!r.ok)throw Error('catalogue');const j=await r.json();const batch=Array.isArray(j)?j:(j.items||j.products||[]);rows=rows.concat(batch);if(batch.length<100)break;offset+=batch.length;}setProducts(rows);let cats=[...new Set(rows.map(p=>p.category).filter(Boolean))].sort();try{const cr=await fetch(API_PATH('/categories'));if(cr.ok){const cj=await cr.json();const saved=(cj.items||[]).map(c=>c.name).filter(Boolean);if(saved.length)cats=[...new Set(saved)].sort()}}catch{}setCategories(['All',...cats]);}catch{setError('The live catalogue could not be reached. Check the API connection and try again.')}finally{if(!silent)setLoading(false)}}
