 const count=cart.reduce((n,x)=>n+x.qty,0),subtotal=cart.reduce((sum,item)=>{const p=item.product||products.find(x=>keyOf(x)===item.key)||{};return sum+Number(p.selling_price??p.price??0)*item.qty},0);
